        totals, count = groups[key]
        for index, value in enumerate(values):
            totals[index] += value
        groups[key] = (totals, count + 1)

    output_header = [args.group_by] + [f"{operation}_{column}" for operation, column, _ in metrics]
    output_rows: list[list[str]] = []
