    try:
        handle = open(path, "r", encoding="utf-8", newline="")
    except (OSError, UnicodeError) as exc:
        raise UserError(f"cannot open input file {path!r}: {exc}") from exc

    try:
        with handle:
            reader = csv.reader(handle, strict=True)
            try:
                header = next(reader)
            except StopIteration:
